/**
 * 03 — assets, vendors, checklists and preventive maintenance.
 *
 * Creates (all through the API, as hendra / admin / putri / agus / bayu / joko): asset types with their own questions, ~55 assets in every status
 * (holders, warranties running out, one lost, one disposed, some in repair), their lifecycle history, 10 vendors with contacts, places, contracts and
 * documents (one blocked; Joko Susilo linked to PT Sejuk Abadi), checklist templates, and 13 maintenance plans whose visits are generated by the
 * app's own generator and worked by the technicians (agus, bayu, joko) so /maintenance/compliance shows on-time, late and missed visits.
 *
 * How the maintenance history is made without touching the app: the generator only makes what is "due now", so for every past occurrence the script
 * briefly sets the plan's counter to that date (SQL, "yearly from that date"), saves the plan through the API (which runs the generator), works the
 * work order through the API as the technician, and only then shifts the timestamps back to the occurrence (see "Backdating" in notes/assets.md).
 * At the end every plan gets its real schedule back and one more save: dates that have no visit are recorded as missed by the generator itself,
 * and the current/upcoming visit is made. Safe to run twice: everything is looked up by name/tag first.
 */
import { writeFileSync, mkdirSync } from "node:fs";

export const name = "assets";

// ------------------------------------------------------------------ date helpers (the organisation's calendar day is Jakarta time)
const pad = (n) => String(n).padStart(2, "0");
const fmt = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;
const todayStr = () => new Date(Date.now() + 7 * 3600e3).toISOString().slice(0, 10);
const parts = (s) => s.split("-").map(Number);
const addDays = (s, n) => { const [y, m, d] = parts(s); return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10); };
const addMonths = (s, n) => { const [y, m, d] = parts(s); const tm = m - 1 + n; const yy = y + Math.floor(tm / 12); const mm = ((tm % 12) + 12) % 12; const last = new Date(Date.UTC(yy, mm + 1, 0)).getUTCDate(); return fmt(yy, mm + 1, Math.min(d, last)); };
const dow = (s) => new Date(`${s}T00:00:00Z`).getUTCDay();
const isWeekend = (s) => [0, 6].includes(dow(s));
const onOrBeforeWorkday = (s) => { while (isWeekend(s)) s = addDays(s, -1); return s; };
const afterWorkdays = (s, n) => { let c = 0; while (c < n) { s = addDays(s, 1); if (!isWeekend(s)) c++; } return s; };
/** ISO instant for a Jakarta wall-clock time. */
const jak = (s, hh, mm = 0) => `${s}T${pad(hh)}:${pad(mm)}:00+07:00`;
const T = todayStr();
const ago = (n) => addDays(T, -n);
const ahead = (n) => addDays(T, n);
/** Occurrence i of a plan, the same arithmetic as the app (always counted from the start). */
const dueOn = (start, unit, every, i) => unit === "day" ? addDays(start, every * i) : unit === "week" ? addDays(start, 7 * every * i) : unit === "month" ? addMonths(start, every * i) : addMonths(start, 12 * every * i);
const startFromAnchor = (anchor, unit, every, n) => unit === "day" ? addDays(anchor, -every * n) : unit === "week" ? addDays(anchor, -7 * every * n) : unit === "month" ? addMonths(anchor, -every * n) : addMonths(anchor, -12 * every * n);
/** Month and year plans keep their day of the month: anything after the 28th moves to the 1st of next month (no end-of-month drift). */
const calm = (s) => { const [y, m, d] = parts(s); return d <= 28 ? s : fmt(m === 12 ? y + 1 : y, m === 12 ? 1 : m + 1, 1); };
const rng = (seed) => () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };

const sqlq = (s) => String(s).replace(/'/g, "''");

